FUNCTION_BLOCK FB
VAR_INPUT
    tankLevel    : REAL;
    outletFlow   : REAL;
    inletPermit  : BOOL;
    resetBtn     : BOOL;
END_VAR
VAR_OUTPUT
    pumpRun          : BOOL;
    alarmHigh        : BOOL;
    alarmLow         : BOOL;
    outletValveOpen  : BOOL;
END_VAR
VAR
    resetBtnPrev : BOOL := FALSE;
END_VAR

(* High level alarm: latches when level >= 85.0 *)
IF tankLevel >= 85.0 THEN
    alarmHigh := TRUE;
END_IF

(* Low level alarm: latches when level <= 15.0 *)
IF tankLevel <= 15.0 THEN
    alarmLow := TRUE;
END_IF

(* Rising edge detection for reset *)
IF resetBtn AND NOT resetBtnPrev THEN
    (* Reset only effective when alarm conditions are cleared *)
    IF tankLevel < 85.0 AND tankLevel > 15.0 THEN
        alarmHigh := FALSE;
        alarmLow  := FALSE;
    END_IF
END_IF
resetBtnPrev := resetBtn;

(* Output control: pump runs when permitted, no high alarm, level below threshold *)
pumpRun := inletPermit AND NOT alarmHigh AND (tankLevel < 85.0);

(* Outlet valve: opens when permitted, no high alarm, no low alarm, level above low threshold *)
outletValveOpen := inletPermit AND NOT alarmHigh AND NOT alarmLow AND (tankLevel > 15.0);

END_FUNCTION_BLOCK
